    fn drop(&mut self) {
        // SAFETY: `unsafe_data` points to a live `Entry` and this atom owns one
        // of its strong references, which we hand back here.
        unsafe {
            Arc::decrement_strong_count(self.unsafe_data.get() as *const Entry);
